<template>
  <AppLoader v-if="isLoadingMetadata" subject="project dashboard" />
  <AppError v-else-if="metadataError" title="Failed to load project dashboard" :error="metadataError" />
  <AppEmpty v-else-if="!metadata" subject="project dashboard" />

  <!-- Canvassing — new tabbed public dashboard. -->
  <section v-else-if="isCanvassing" class="flex flex-col gap-10">
    <PageTitle :subtitle="metadata.short_description">
      <template #title>
        <span class="flex flex-row items-center gap-2">
          {{ metadata.name }}
          <Badge class="text-base font-normal" :variant="getProjectStatus(metadata.status).variant">{{
            getProjectStatus(metadata.status).label
          }}</Badge>
        </span>
      </template>
    </PageTitle>
    <CanvassingProjectDashboard
      is-public
      tab="overview"
      :dashboard-hash="dashboardHash"
      :project-start-end-date="{ start: metadata.start_date, end: metadata.end_date }"
      :project-regions="metadata.regions"
    />
  </section>

  <!-- Signature / legacy — deprecated monolithic public dashboard (unchanged). -->
  <template v-else>
    <AppLoader v-if="isLoadingMono" subject="project dashboard" />
    <AppError v-else-if="monoError" title="Failed to load project dashboard" :error="monoError" />
    <AppEmpty v-else-if="!monoData" subject="project dashboard" />
    <section v-else class="flex flex-col gap-10">
      <PageTitle :subtitle="monoData.project_info.short_description">
        <template #title>
          <span class="flex flex-row items-center gap-2">
            {{ monoData.project_info.name }}
            <Badge class="text-base font-normal" :variant="getProjectStatus(monoData.project_info.status).variant">{{
              getProjectStatus(monoData.project_info.status).label
            }}</Badge>
          </span>
        </template>
      </PageTitle>
      <div class="flex flex-col gap-4">
        <ProjectDashboardNavigation
          :params="monoParams"
          :project-start-end-date="{
            start: monoData.project_info.start_date,
            end: monoData.project_info.end_date,
          }"
          :project-regions="monoData.project_info.regions"
          is-public
          :is-loading="isLoadingMono"
        />
        <div v-if="monoData.charts" class="grid grid-cols-12 gap-4">
          <DashboardChartsCard
            :charts="monoData.charts"
            :params="monoParams"
            :dashboard-id="dashboardHash"
            :map-date-range="{
              startDate: monoParams.start_date ?? monoData.project_info.start_date,
              endDate: monoParams.end_date ?? monoData.project_info.end_date,
            }"
            :query-key="['share.project.dashboard.hash', dashboardHash, monoParams]"
            map-type="public-project"
          />
        </div>
      </div>
    </section>
  </template>
</template>

<script setup lang="ts">
import { getProjectPublicDashboard } from '~/client';
import type { GetProjectPublicDashboardData } from '~/client';
import { getProjectStatus } from '~/constants/projects';

definePageMeta({
  layout: 'share',
  auth: false,
  backGroup: 'share-project-dashboard',
});

const route = useRoute('share-project-dashboard-hash');
const dashboardHash = computed(() => route.params.hash);
const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

const {
  metadata,
  error: metadataError,
  isLoading: isLoadingMetadata,
  isCanvassing,
} = usePublicDashboardMetadata(dashboardHash);

// The deprecated monolithic public dashboard — used only for non-canvassing
// (signature/legacy) projects once metadata has resolved the type.
const monoParams = computed(() => {
  const urlParams: GetProjectPublicDashboardData['query'] = {
    start_date: route.query.start_date ? route.query.start_date.toString() : undefined,
    end_date: route.query.end_date ? route.query.end_date.toString() : undefined,
    regions: processArrayQueryParameterFromUrl(route.query.regions),
    timezone,
  };

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as GetProjectPublicDashboardData['query'];
});

const {
  data: monoData,
  error: monoError,
  isLoading: isLoadingMono,
} = useQuery({
  key: () => ['share.project.dashboard.hash', dashboardHash.value, monoParams.value],
  query: () =>
    getProjectPublicDashboard({ composable: '$fetch', path: { public_hash: dashboardHash.value }, query: monoParams }),
  placeholderData: (previousData) => previousData,
  enabled: () => !!dashboardHash.value && !!metadata.value && !isCanvassing.value,
});

useHead({
  title: computed(() => `${metadata.value?.name ?? ''} Dashboard`),
});
</script>
